/* The project count in words, for copy like "All seventeen projects". Pages
   used to hardcode "twelve", which went stale the day a case study was added;
   reading the length here keeps every count in step with the array above. */
const COUNT_WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty", "twenty-one", "twenty-two", "twenty-three", "twenty-four", "twenty-five"];
export const countWord = (n) => COUNT_WORDS[n] ?? String(n);
export const projectCountWord = countWord(projects.length);
